#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .001
#define TAU 6.283185
#define PI 3.141592
#define S smoothstep
#define T iTime

mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}


vec2 opRepBox( in vec2 p, in float rep, in ivec2 ib ) // inigo quilez <3
{
    vec2 b = rep*vec2(ib>>1);
    p = abs(p);
    vec2  w = p - b;
    bool  q = w.x > w.y;
    float u = q ? min(p.y,b.y) : min(p.x,b.x);
    u = round(u/rep)*rep;
    return q ? vec2(w.x,p.y-u) : vec2(p.x-u,w.y);
}

float sdBox(vec3 p, vec3 s) { // inigo quilez
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

float sdBoxFrame( vec3 p, vec3 b, float e ) // inigo quilez
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;
  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0))+min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0))+min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0))+min(max(q.x,max(q.y,p.z)),0.0));
}


vec2 N(float angle) {
    return vec2(sin(angle), cos(angle));
}

float GetDist(vec3 p) {

    p.xy *= Rot(iTime*.5);
    p.yz *= Rot(iTime*.5);
    //p.xz *= Rot(iTime*.1);

    vec3 q = p; 
    q.xz = opRepBox(q.xz, 2.5, ivec2(4, 3));

    float bx = sdBoxFrame(q, vec3(1, 1, 1), .25) ;

    float cut = sdBox(q, vec3(1));

    float bx1 = sdBoxFrame(q, vec3(.5, .5, 2), .1);

    float bx2 = sdBoxFrame(q, vec3(2, .5, .5), .1);

    float bx3 = sdBoxFrame(q, vec3(.5, 2, .5), .1);


    float d = max(10. * bx, 10. * cut);

    d = min(d, bx1);

    d = min(d, bx2);

    d = min(d, bx3);

    return d;
}

float RayMarch(vec3 ro, vec3 rd) {
	float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        dO += dS;
        if(dO>MAX_DIST || abs(dS)<SURF_DIST) break;
    }

    return dO;
}

vec3 GetNormal(vec3 p) {
    vec2 e = vec2(.000001, 0);
    vec3 n = GetDist(p) - 
        vec3(GetDist(p-e.xyy), GetDist(p-e.yxy),GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 
        f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u;
    return normalize(i);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 m = iMouse.xy/iResolution.xy;

    vec3 ro = vec3(0, 6, -3);
    ro.yz *= Rot(-m.y*PI+1.);
    ro.xz *= Rot(-m.x*TAU);

    vec3 rd = GetRayDir(uv, ro, vec3(0,0.,0), .5);
    vec3 col = vec3(0);

    float d = RayMarch(ro, rd);

    if(d<MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = GetNormal(p);
        vec3 r = reflect(rd, n);

        float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        col = vec3(dif);

        col = n*.5+.5;
        col *= texture(iChannel0, r).rgb;
    }

    //col *= 0.;

    //vec2 st = Koch(uv)*4.;
    //col = vec3(-st.y);

    col = pow(col, vec3(.55));	// gamma correction

  float gray = 0.5 * (col.r + col.g + col.b);
        // mix white and black by the value of step(threshold, gray)
    float threshold = 0.5;
    if(gray > threshold)
    {
     // white
     col.rgb = vec3(1.0);   
    }
    else
    {
     // black
     col.rgb = vec3(0.0);
    }

    fragColor = vec4(col, 1.0);
}
